def recipe_env(name: str, chip: int) -> dict:
    port = 8476 + chip
    single = {"TPU_CHIPS_PER_PROCESS_BOUNDS": "1,1,1", "TPU_PROCESS_BOUNDS": "1,1,1", "TPU_RUNTIME_METRICS_PORTS": str(8431 + chip)}
    if name == "visible_chips":
        return {**single, "TPU_VISIBLE_CHIPS": str(chip), "TPU_PROCESS_PORT": str(port),
                "TPU_PROCESS_ADDRESSES": f"localhost:{port}", "CLOUD_TPU_TASK_ID": "0"}
    if name == "visible_chips_host_bounds":
        return {**recipe_env("visible_chips", chip), "TPU_CHIPS_PER_HOST_BOUNDS": "1,1,1", "TPU_HOST_BOUNDS": "1,1,1"}
    if name == "visible_devices_mesh":
        return {**single, "TPU_VISIBLE_DEVICES": str(chip), "TPU_MESH_CONTROLLER_ADDRESS": f"localhost:{port}",
                "TPU_MESH_CONTROLLER_PORT": str(port)}
    raise ValueError(name)


SMOKE = (
    "import time, torch, torch_xla, torch_xla.runtime as xr\n"
    "dev = torch_xla.device()\n"
    "a = torch.randn(4096, 4096, device=dev, dtype=torch.bfloat16)\n"
    "c = a @ a; torch_xla.sync(); c.cpu()\n"
    "t = time.time()\n"
    "for _ in range(20): c = a @ a\n"
    "torch_xla.sync(); c.cpu()\n"
    "dt = time.time() - t\n"
    "print('SMOKE devices', xr.global_runtime_device_count(), 'tflops', round(20 * 2 * 4096**3 / dt / 1e12, 1))\n"
)


def clear_tpu_locks() -> None:
    # libtpu leaves a lock file; a killed process can leave it behind and block the next one
    for path in ("/tmp/libtpu_lockfile",):
        if os.path.exists(path):
            os.remove(path)
            log(f"removed {path}")


def try_recipe(name: str) -> bool:
    clear_tpu_locks()
    procs = []
    for chip in range(CHIPS):
        env = {**os.environ, "PJRT_DEVICE": "TPU", **recipe_env(name, chip)}
        procs.append(subprocess.Popen([sys.executable, "-c", SMOKE], env=env, stdout=subprocess.PIPE,
                                      stderr=subprocess.STDOUT, text=True))
    ok = 0
    began = time.time()
    for chip, proc in enumerate(procs):
        try:
            out, _ = proc.communicate(timeout=max(1.0, 300 - (time.time() - began)))  # one shared 300 s budget for all 8
        except subprocess.TimeoutExpired:
            proc.kill()
            proc.communicate()
            out = "TIMEOUT"
        smoke = [line for line in out.splitlines() if line.startswith("SMOKE")]
        good = proc.returncode == 0 and smoke and smoke[0].split()[2] == "1"
        ok += bool(good)
        log(f"recipe {name} chip {chip}: rc {proc.returncode} {smoke[0] if smoke else out[-600:]}")
    return ok == CHIPS


def try_pool() -> bool:
    """Fallback: torch_xla.launch, one process per chip (mhc_lab.xla_pool)."""
    clear_tpu_locks()
    env = {**os.environ, "PJRT_DEVICE": "TPU", "PYTHONPATH": str(SRC)}
    cmd = [sys.executable, "-m", "mhc_lab.xla_pool", str(JOBS_PATH), str(OUT), str(DATA), str(START + DEADLINE_SECONDS), "--smoke"]
    try:
        result = subprocess.run(cmd, env=env, capture_output=True, text=True, timeout=600)
        out = result.stdout + result.stderr
    except subprocess.TimeoutExpired:
        out = "TIMEOUT"
    smoke = [line for line in out.splitlines() if line.startswith("SMOKE")]
    for line in smoke:
        log(f"pool {line}")
    if not smoke:
        log(f"pool smoke failed: {out[-1500:]}")
    return len({line.split()[2] for line in smoke}) == CHIPS


def try_single() -> bool:
    """The whole host in one process, no pinning: does the TPU work at all?"""
    clear_tpu_locks()
    env = {**os.environ, "PJRT_DEVICE": "TPU"}
    try:
        result = subprocess.run([sys.executable, "-c", SMOKE], env=env, capture_output=True, text=True, timeout=300)
        out = result.stdout + result.stderr
    except subprocess.TimeoutExpired:
        out = "TIMEOUT"
    smoke = [line for line in out.splitlines() if line.startswith("SMOKE")]
    log(f"single process: {smoke[0] if smoke else out[-1500:]}")
    return bool(smoke)


def descendants(root: int) -> list[int]:
    """Every process below root in the parent-pid tree (Linux /proc)."""
    children = {}
    for entry in os.listdir("/proc"):
        if not entry.isdigit():
            continue
        try:
            stat = Path(f"/proc/{entry}/stat").read_text()
        except OSError:
            continue
        ppid = int(stat.rsplit(")", 1)[1].split()[1])  # field 4; the command name in field 2 may contain spaces
        children.setdefault(ppid, []).append(int(entry))
    found = []
    stack = [root]
    while stack:
        for child in children.get(stack.pop(), []):
            found.append(child)
            stack.append(child)
    return found


def kill_descendants() -> None:
    """SIGTERM, then SIGKILL, every process this launcher started (directly or not)."""
    for sig in (signal.SIGTERM, signal.SIGKILL):
        for pid in descendants(os.getpid()):
            try:
                os.kill(pid, sig)
            except (ProcessLookupError, PermissionError):
                pass
        time.sleep(5)


def watchdog() -> None:
    """At HARD_STOP_SECONDS kill everything this kernel started and exit, so a hung job cannot burn the session's quota."""
    time.sleep(max(0.0, START + HARD_STOP_SECONDS - time.time()))
    log("hard stop: killing all child processes")
    (OUT / "hard_stop.txt").write_text(f"hard stop at {time.time() - START:.0f}s")
    kill_descendants()
    os._exit(0)


