def run_job(job: dict, run_dir: Path, cmd: list, env: dict, began: float) -> str:
    """Run one job, killing it if it never logs a first step or runs past the job timeout. Returns its exit status."""
    first_step_timeout = job.get("first_step_timeout", FIRST_STEP_TIMEOUT_SECONDS)
    metrics = run_dir / "metrics.jsonl"
    with open(run_dir / "log.txt", "w") as out:
        proc = subprocess.Popen(cmd, env=env, stdout=out, stderr=subprocess.STDOUT)
        while proc.poll() is None:
            time.sleep(10)
            age = time.time() - began
            no_step = not metrics.exists() or metrics.stat().st_size == 0
            if proc.poll() is None and no_step and age > first_step_timeout:
                proc.kill()
                proc.wait()
                return f"killed: no first step after {first_step_timeout}s"
            if proc.poll() is None and age > job.get("timeout", JOB_TIMEOUT_SECONDS):
                proc.kill()
                proc.wait()
                return "killed: job timeout"
    return f"exit {proc.returncode}"


def gate_passed(job: dict, run_dir: Path) -> bool:
    summary = run_dir / "summary.json"
    tok_s = json.loads(summary.read_text()).get("tok_s") if summary.exists() else None
    log(f"gate {job['name']}: tok/s {tok_s}, needs {job['gate_min_tok_s']}")
    return tok_s is not None and tok_s >= job["gate_min_tok_s"]


def worker(chip: int) -> None:
    while True:
        with lock:
            if not queue:
                return
            for job in [j for j in queue if status.get(j.get("only_if_failed"), "").startswith("exit 0")]:
                status[job["name"]] = f"skipped ({job['only_if_failed']} succeeded)"
                queue.remove(job)
            waiting = [j for j in queue if j.get("only_if_failed") and j["only_if_failed"] not in status]
            elapsed = time.time() - START
            fits = [j for j in queue if j not in waiting
                    and elapsed + j.get("expected_seconds", longest[0]) < HARD_STOP_SECONDS - 600]
            if elapsed > DEADLINE_SECONDS or not (fits or waiting):
                for job in queue:
                    status[job["name"]] = "skipped (deadline)"
                queue.clear()
                return
            if not fits:
                return  # only fallbacks of running jobs are left: the chip a failed job frees will take its fallback
            job = fits[0]  # the first job in the queue that can still end before the hard stop
            queue.remove(job)
        began = time.time()
        run_dir = OUT / "runs" / job["name"]
        run_dir.mkdir(parents=True, exist_ok=True)
        module = job.get("module", "mhc_lab.train_xla")
        cmd = [sys.executable, "-m", module, "--out", str(run_dir), "--data-dir", str(DATA), *job["args"]]
        env = {**os.environ, "PJRT_DEVICE": "TPU", "PYTHONPATH": str(SRC)}
        if recipe is not None:
            env.update(recipe_env(recipe, chip))
        code = run_job(job, run_dir, cmd, env, began)
        took = time.time() - began
        with lock:
            longest[0] = max(longest[0], took)
            status[job["name"]] = f"{code} in {took:.0f}s on chip {chip}"
            log(f"{job['name']}: {status[job['name']]}")
            if code != "exit 0":  # the job's own log only comes back with the final download: show why it failed now
                tail = (run_dir / "log.txt").read_text(errors="replace").splitlines()[-12:]
                log("\n".join(line[:300] for line in tail))
            if "gate_min_tok_s" in job and not gate_passed(job, run_dir):
                log(f"gate {job['name']} failed: no further jobs start")
                for waiting in queue:
                    status[waiting["name"]] = f"skipped (gate {job['name']} failed)"
                queue.clear()
            (OUT / "status.json").write_text(json.dumps(status, indent=1))


workers = CHIPS if recipe is not None else 1
threads = [threading.Thread(target=worker, args=(c,)) for c in range(workers)]
for t in threads:
    t.start()
for t in threads:
    t.join()
for job in queue:
    status[job["name"]] = "skipped (not run)"
(OUT / "status.json").write_text(json.dumps(status, indent=1))
log("all done")
